import fs from "node:fs";
import path from "node:path";

const TYPESCRIPT_HEADER = `// SPDX-FileCopyrightText: Copyright (c) 2026, NVIDIA CORPORATION & AFFILIATES.
// All rights reserved.
// SPDX-License-Identifier: Apache-2.0
// @generated by ANTLR 4.9.0-SNAPSHOT — DO NOT EDIT.

`;

function generatedFiles(directory) {
    return fs
        .readdirSync(directory, { withFileTypes: true })
        .flatMap((entry) => {
            const candidate = path.join(directory, entry.name);
            return entry.isDirectory()
                ? generatedFiles(candidate)
                : [candidate];
        });
}

for (const generatedPath of generatedFiles(process.argv[2])) {
    let content = fs
        .readFileSync(generatedPath, "utf8")
        .replace(/[ \t]+$/gm, "");

    if (
        generatedPath.endsWith(".ts") &&
        !content.startsWith(TYPESCRIPT_HEADER)
    ) {
        content = TYPESCRIPT_HEADER + content;
    }

    fs.writeFileSync(generatedPath, content);
}
